async function collections(pattern){return(await Promise.all((await readdir(path.join(site,'data'))).filter(name=>pattern.test(name)).map(name=>json('data/'+name)))).flat();}
function walk(flow, choices, domain){const value=flow.walkFromRoot(choices,domain);assert.equal(value.consumed,choices.length);return value;}
function enter(flow,state){for(let budget=0;flow.evaluateState(state).current.type==='route';++budget){assert(budget<100);state=flow.enterFlowRoute(state);}return state;}
function replay(flow,choices,domain){let state=flow.initialState(domain);for(const answer of choices)state=flow.answerState(enter(flow,state),answer);return enter(flow,state);}
function weight(state){return state.answers.length+(state.trail??[]).reduce((sum,context)=>sum+context.answers.length+1,0);}
const svgCache=new Map();let html;
function svgFor(flow,graph){if(svgCache.has(graph.id))return svgCache.get(graph.id);
  const svg=flow.renderFlowSvg(graph);let count=0;
  for(const node of graph.nodes){assert(svg.includes(`data-node="${node.id}"`));
    if(node.type==='question')for(const option of flow.getNodeOptions(node)){
      ++count;assert(svg.includes(`data-edge="${node.id}:${option.id}:${node.answers[option.id]}"`));
      assert(svg.includes(`<title>${xml(option.label)}</title>`),'full SVG answer label');}
    if(node.type==='result')for(const id of node.techniques??[])assert(svg.includes(`href="/flowchartcp/techniques/${id}/"`));}
  assert.equal((svg.match(/class="flow-edge /g)??[]).length,count);svgCache.set(graph.id,svg);return svg;
}
function historical(fresh,old,label){
  assert.deepEqual(fresh.records.map(row=>row.problemId),old.records.map(row=>row.problemId),label+': fixed identities');
  for(const [key,value] of Object.entries(old))if(key!=='records'){
    assert(Object.hasOwn(fresh,key),label+': existing top field '+key);
    assert.equal(digest(fresh[key]),digest(value),label+': deep preserve '+key);}
  const projected=structuredClone(fresh);
  projected.records=fresh.records.map((row,index)=>{
    const initial=old.records[index],copy={};
    for(const key of Object.keys(initial)){assert(Object.hasOwn(row,key),label+'/'+row.problemId+': existing row field '+key);copy[key]=row[key];}
    assert.equal(digest(copy),digest(initial),label+'/'+row.problemId+': every prior field including prior resolutions');return copy;
  });
  return projected;
}

